import { Component, forwardRef, input } from '@angular/core';
import { FormsModule, NG_VALUE_ACCESSOR } from '@angular/forms';
import { NzInputModule } from 'ng-zorro-antd/input';
import { HrmControl } from '../shared/hrm-control';
import { HrmSize, HrmStatus, toNzStatus } from '../data-entry/hrm-input';

const toNz = (s: HrmSize) => (s === 'sm' ? 'small' : s === 'lg' ? 'large' : 'default');

/** hrm-phone — domain wrapper: SĐT, chỉ nhận số, prefix quốc gia. CVA string. */
@Component({
  selector: 'hrm-phone',
  imports: [FormsModule, NzInputModule],
  template: `
    <nz-input-group [nzAddOnBefore]="dialCode()" [nzStatus]="toNzStatus(status())">
      <input
        nz-input
        type="tel"
        inputmode="numeric"
        [ngModel]="value()"
        (ngModelChange)="onInput($event)"
        (blur)="markTouched()"
        [placeholder]="placeholder()"
        [nzSize]="toNz(size())"
        [disabled]="disabled()"
        maxlength="11" />
    </nz-input-group>
  `,
  host: { class: 'hrm-phone', '[class.hrm-status-success]': "status() === 'success'" },
  providers: [{ provide: NG_VALUE_ACCESSOR, useExisting: forwardRef(() => HrmPhone), multi: true }],
})
export class HrmPhone extends HrmControl<string> {
  readonly placeholder = input('Số điện thoại');
  readonly dialCode = input('+84');
  readonly size = input<HrmSize>('md');
  readonly status = input<HrmStatus>('');
  protected readonly toNz = toNz;
  protected readonly toNzStatus = toNzStatus;

  protected onInput(v: string): void {
    this.emit((v ?? '').replace(/[^\d]/g, ''));
  }
}
